 WHERE json_extract(address,'$.attentionDonorId')=NEW.id;
 UPDATE cf_in_kind_acknowledgments SET recipient_address=NULL,subject='[erased]',body='[erased]' WHERE json_extract(recipient_address,'$.attentionDonorId')=NEW.id;
